<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,allPages,fmt} from '../api'
import {apiErrorMessage} from '../errors'
import {useWorkspace} from '../store'
import {kinds,sections} from '../platform'
import Icon from '../components/Icon.vue'
import UiCaseSteps from '../components/UiCaseSteps.vue'
import PreparedDataSelect from '../components/PreparedDataSelect.vue'
const route=useRoute(),router=useRouter(),store=useWorkspace(),section=computed(()=>sections[String(route.meta.catalog)]),kind=ref(''),uiPlatform=ref<'app'|'web'>('app'),items=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),selected=ref<any[]>([]),dialog=ref(false),form=ref<any>({}),configText=ref('{}'),saving=ref(false),parents=ref<any[]>([]),models=ref<any[]>([]),detail=ref<any>(null),versions=ref<any[]>([]),files=ref<any[]>([]),envs=ref<any[]>([]),environment=ref<number|null>(null),mode=ref('live'),query=ref(''),hits=ref<any[]>([]),searching=ref(false),stats=ref<any>(null),importDialog=ref(false),importText=ref(''),syncOpenapi=ref(false),fileInput=ref<HTMLInputElement>(),requirementInput=ref<HTMLInputElement>(),uploadId=ref<number|null>(null),machineStatuses=ref<Record<number,any>>({}),checkingMachines=ref<number[]>([]),runDialog=ref(false),pendingRows=ref<any[]>([]),preparationText=ref('{}'),requestBaseUrl=ref(''),requestPath=ref(''),requestParamsText=ref('{}'),repeatCount=ref(1),stallThresholdMs=ref(5000),running=ref(false),pageObjects=ref<any[]>([]),uiResources=ref<any[]>([]),publicProfiles=ref<any[]>([]),profileDialog=ref(false),profileId=ref<number|null>(null),applyingProfile=ref(false),converting=ref(false),flowCases=ref<any[]>([])
let version=0
const failureAnalysisModelId=ref<number|null>(null)
async function load(){if(!store.projectId||!kind.value)return;const n=++version;loading.value=true;try{const {data}=await api.get('entities/',{params:{project:store.projectId,kind:kind.value,page:page.value,search:search.value,...(kind.value==='ui_case'?{platform:uiPlatform.value}:{})}});if(n===version){items.value=data.results;total.value=data.count;selected.value=[];if(kind.value==='machine'){const statuses=await Promise.all(data.results.map((row:any)=>api.get(`entities/${row.id}/connection_status/`).then(r=>[row.id,r.data]).catch(()=>[row.id,{checked:false,message:'状态读取失败'}])));if(n===version)machineStatuses.value=Object.fromEntries(statuses)}}}finally{if(n===version)loading.value=false}}
watch(()=>[route.meta.catalog,store.projectId],async()=>{kind.value=section.value.tabs[0];page.value=1;detail.value=null;dialog.value=false;await load();models.value=await allPages('resources/',{project:store.projectId,kind:'model'});envs.value=await allPages('entities/',{project:store.projectId,kind:route.meta.catalog==='ui-testing'?'ui_environment':'environment'});environment.value=null},{immediate:true})
function filter(){page.value=1;load()}
const referencedRunVariables=computed(()=>{
 const names=new Set<string>()
 for(const row of pendingRows.value){
  for(const match of JSON.stringify(row.config||{}).matchAll(/\{\{([\w:.-]+)\}\}/g))if(!match[1].startsWith('secret:'))names.add(match[1])
 }
 return [...names]
})
function modelLocation(resource:any){
 try{
  const hostname=new URL(resource.endpoint).hostname.toLowerCase()
  const local=hostname==='localhost'||hostname==='127.0.0.1'||hostname==='::1'||hostname==='host.docker.internal'||hostname.endsWith('.local')||
   /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(hostname)
  return local?'本地':'外部'
 }catch{return '未识别'}
}
const failureAnalysisModels=computed(()=>models.value.filter((item:any)=>item.enabled&&item.settings?.provider_type!=='h2o_decisions'))
function fillPreparationExample(){
 const names=referencedRunVariables.value
 const variables=names.length?names:['tenant_id','order_id','token']
 const example=Object.fromEntries(variables.map(name=>{
  if(/secret|password|token|api.?key/i.test(name))return [name,'']
  if(/user|account|login/i.test(name))return [name,'test_user']
  if(/email/i.test(name))return [name,'tester@example.test']
  if(/phone|mobile/i.test(name))return [name,'TEST_PHONE']
  if(/tenant/i.test(name))return [name,'test_tenant_001']
  if(/order/i.test(name))return [name,'test_order_001']
  return [name,`test_${name}`]
 }))
 preparationText.value=JSON.stringify(example,null,2)
}
function exportItems(format:'json'|'xlsx'){
 const params=new URLSearchParams({project:String(store.projectId),kind:kind.value})
 if(kind.value==='ui_case')params.set('platform',uiPlatform.value)
 if(search.value.trim())params.set('search',search.value.trim())
 if(format==='xlsx')params.set('export_format','xlsx')
 window.location.assign(`/api/entities/export/?${params.toString()}`)
}
watch(uiPlatform,filter)
watch(()=>route.query.platform,(value)=>{if(value==='app'||value==='web')uiPlatform.value=value},{immediate:true})
watch(()=>route.query.tab,(value)=>{const requested=String(value||'');if(route.meta.catalog==='ui-testing'&&section.value.tabs.includes(requested)&&kind.value!==requested){kind.value=requested;page.value=1;load()}},{immediate:true})
function uiTemplate(platform:'app'|'web'){return platform==='app'?{platform:'app',priority:'P1',test_type:'functional',preconditions:'',notes:'',automation_status:'needs_mapping',executor:'mobile-mcp',package_name:'',device_id:'',mcp_resource_id:null,design_steps:[{action:'填写操作步骤',expected:'填写预期结果'}],steps:[]}:{...JSON.parse(JSON.stringify(kinds.ui_case.config)),platform:'web',priority:'P1',test_type:'functional',preconditions:'',notes:''}}
async function testMachine(row:any){checkingMachines.value.push(row.id);try{const {data}=await api.post(`entities/${row.id}/test_connection/`);machineStatuses.value={...machineStatuses.value,[row.id]:data};data.connected?ElMessage.success(`${data.model} 连接成功`):ElMessage.warning(data.message)}finally{checkingMachines.value=checkingMachines.value.filter(id=>id!==row.id)}}
function changeMachineExecutor(value:string){let config:any={};try{config=JSON.parse(configText.value)}catch{}config.executor=value;if(value==='local-android-adb')config.serial=config.serial||'';else delete config.serial;form.value.config=config;configText.value=JSON.stringify(config,null,2)}
async function edit(row?:any){form.value=row?JSON.parse(JSON.stringify(row)):{name:'',content:'',parent:null,config:kind.value==='ui_case'?uiTemplate(uiPlatform.value):JSON.parse(JSON.stringify(kinds[kind.value].config))};if(kind.value==='ui_data'){form.value.config.data_type=form.value.config.data_type||'variables';form.value.config.app_profile=form.value.config.app_profile||{app_name:'',package_name:'',device_id:'',mcp_resource_id:null};form.value.config.web_profile=form.value.config.web_profile||{base_url:'',browser:'chromium'};configText.value=JSON.stringify(form.value.config.variables||{},null,2);uiResources.value=await allPages('resources/',{project:store.projectId,kind:'mcp'})}else configText.value=JSON.stringify(form.value.config,null,2);parents.value=await allPages('entities/',{project:store.projectId,kind:kind.value==='knowledge_document'?'knowledge':kind.value==='requirement'?'requirement':'module'});if(kind.value==='ui_case'){pageObjects.value=await allPages('entities/',{project:store.projectId,kind:'page'});uiResources.value=await allPages('resources/',{project:store.projectId,kind:'mcp'})}if(kind.value==='ui_flow')await loadFlowCases();dialog.value=true}
async function loadFlowCases(reset=false){if(!store.projectId||!form.value.config)return;if(reset)form.value.config.case_ids=[];flowCases.value=await allPages('entities/',{project:store.projectId,kind:'ui_case',platform:form.value.config.platform||'web'})}
function moveFlowCase(index:number,delta:number){const ids=form.value.config.case_ids||[],target=index+delta;if(target<0||target>=ids.length)return;[ids[index],ids[target]]=[ids[target],ids[index]]}
function removeUiStep(index:number){const config=form.value.config;(config.platform==='app'&&config.automation_status==='needs_mapping'?config.design_steps:config.steps).splice(index,1);form.value={...form.value}}
function setUiStepMode(executable:boolean){const config=form.value.config;if(config.platform==='app'){if(executable){config.automation_status='ready';config.executor='mobile-mcp';config.steps=[{action:'launch_app'},...(config.design_steps||[]).filter((step:any)=>step.expected?.trim()).map((step:any)=>({action:'assert_text',value:step.expected.trim()}))];config.package_name=config.package_name||'';config.device_id=config.device_id||'';config.mcp_resource_id=config.mcp_resource_id||null}else{config.automation_status='needs_mapping';config.executor='mobile-mcp';config.steps=[];config.design_steps=config.design_steps?.length?config.design_steps:[{action:'填写操作步骤',expected:'填写预期结果'}]}}form.value={...form.value}}
async function save(){saving.value=true;try{let config;if(['ui_case','ui_flow'].includes(kind.value))config=form.value.config;else{try{const parsed=JSON.parse(configText.value);config=kind.value==='ui_data'?{...form.value.config,variables:parsed}:parsed}catch{ElMessage.warning('配置 JSON 格式不正确');return}}const payload={...form.value,config,project:store.projectId,kind:kind.value};await(form.value.id?api.patch(`entities/${form.value.id}/`,payload):api.post('entities/',payload));dialog.value=false;ElMessage.success('已保存，新版本已记录');await load()}finally{saving.value=false}}
async function openProfileApply(){const dataType=uiPlatform.value==='app'?'app_profile':'web_profile';publicProfiles.value=(await allPages('entities/',{project:store.projectId,kind:'ui_data'})).filter((item:any)=>item.config?.data_type===dataType);if(!publicProfiles.value.length){ElMessage.warning(`请先在“公共数据”中创建并保存 ${uiPlatform.value==='app'?'App':'Web'} 执行配置`);return}profileId.value=publicProfiles.value[0].id;profileDialog.value=true}
async function applyProfile(){if(!profileId.value||!selected.value.length)return;applyingProfile.value=true;try{const action=uiPlatform.value==='app'?'apply_ui_profile':'apply_web_profile';const {data}=await api.post(`entities/${profileId.value}/${action}/`,{case_ids:selected.value.map((row:any)=>row.id)});profileDialog.value=false;ElMessage.success(`已将公共配置应用到 ${data.applied} 条选中用例`);await load()}finally{applyingProfile.value=false}}
async function convertSelected(){const rows=selected.value.filter((row:any)=>row.config?.platform===uiPlatform.value&&(row.config?.automation_status==='needs_mapping'||row.config?.verification_status==='unverified'));if(!rows.length)return;converting.value=true;try{const outcomes=await Promise.all(rows.map(async(row:any)=>{try{return (await api.post(`entities/${row.id}/make_ui_executable/`,{refresh:row.config?.automation_status!=='needs_mapping'})).data}catch(error:unknown){return {id:row.id,error:apiErrorMessage(error,'转换失败',['detail','config'])}}}));const ok=outcomes.filter((item:any)=>item.status==='ready').length,unmapped=outcomes.reduce((sum:number,item:any)=>sum+(item.unmapped?.length||0),0),failed=outcomes.filter((item:any)=>item.error);if(failed.length)ElMessage.warning(`已转换 ${ok} 条；${failed.length} 条未转换，请检查配置：${String(failed[0].error).slice(0,100)}`);else if(unmapped)ElMessage.warning(`已生成 ${ok} 条未验证流程；${unmapped} 个步骤需在公共数据补充或手动核对，可在用例编辑器查看`);else ElMessage.success(`已生成 ${ok} 条未验证的 ${uiPlatform.value==='app'?'Mobile MCP':'Playwright'} 执行流程；执行结果仍需实机/浏览器验证`);await load()}finally{converting.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm(`删除「${row.name}」及其版本记录？`,'确认删除',{type:'warning'})}catch{return}await api.delete(`entities/${row.id}/`);filter()}
async function view(row:any){detail.value=row;versions.value=(await api.get(`entities/${row.id}/revisions/`)).data;files.value=await allPages('artifacts/',{project:store.projectId,entity:row.id});hits.value=[];stats.value=row.kind==='knowledge'?(await api.get(`entities/${row.id}/statistics/`)).data:null}
async function restore(v:any){await api.post(`entities/${detail.value.id}/restore/`,{version:v.version});ElMessage.success('已恢复为新版本');detail.value=(await api.get(`entities/${detail.value.id}/`)).data;view(detail.value);load()}
function upload(row:any){uploadId.value=row.id;fileInput.value?.click()}
async function onFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const data=new FormData();data.append('entity',String(uploadId.value));data.append('file',file);try{const res=await api.post('artifacts/',data);ElMessage.success('文件已保存，后台正在解析');router.push('/tasks/'+res.data.job)}finally{input.value=''}}
async function importRequirement(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;const data=new FormData();data.append('project',String(store.projectId));data.append('file',file);try{const res=await api.post('entities/import_requirement/',data);ElMessage.success('需求已创建，正在后台解析');await load();router.push('/tasks/'+res.data.job)}finally{input.value=''}}
function prepareRun(rows:any[]){if(kind.value==='ui_case'&&rows.some(r=>r.config?.automation_status==='needs_mapping')){ElMessage.warning('请先转换未验证步骤，再运行 UI 用例');return}if(kind.value==='ui_flow'){const flow=rows[0];if(flow.config?.status!=='ready'){ElMessage.warning('测试流程当前为草稿，点击“编辑”将流程状态改为“就绪”并保存后即可执行');return}if(!flow.config?.case_ids?.length){ElMessage.warning('测试流程尚未关联 UI 用例，请先编辑流程并选择用例');return}}pendingRows.value=rows;failureAnalysisModelId.value=null;repeatCount.value=1;stallThresholdMs.value=5000;preparationText.value='{}';const env=envs.value.find(e=>e.id===environment.value);requestBaseUrl.value=env?.config?.base_url||'';requestPath.value=rows.length===1?rows[0].config?.url||'':'';requestParamsText.value=JSON.stringify(rows.length===1?rows[0].config?.params||{}:{},null,2);runDialog.value=true}
async function submitRun(){let preparationData,requestParams;try{preparationData=JSON.parse(preparationText.value);requestParams=JSON.parse(requestParamsText.value)}catch{ElMessage.warning('准备数据和请求参数必须是有效 JSON');return}if(!preparationData||Array.isArray(preparationData)||typeof preparationData!=='object'||!requestParams||Array.isArray(requestParams)||typeof requestParams!=='object'){ElMessage.warning('准备数据和请求参数必须是 JSON 对象');return}running.value=true;try{const rows=pendingRows.value;if(kind.value==='ui_flow'){const {data}=await api.post(`entities/${rows[0].id}/run_ui_flow/`,{mode:mode.value,environment_id:environment.value??rows[0].config.environment_id,preparation_data:preparationData});runDialog.value=false;router.push('/tasks/'+data.id);return}const requestOverrides=kind.value==='api'?{base_url:requestBaseUrl.value.trim(),path:requestPath.value.trim(),params:requestParams}:{};const payload:any={entity_ids:rows.map(r=>r.id),environment_id:environment.value??rows[0].config.environment_id,preparation_data:preparationData,request_overrides:requestOverrides};if(kind.value==='ui_case'&&uiPlatform.value==='web'){payload.repeat_count=repeatCount.value;payload.stall_threshold_ms=stallThresholdMs.value}const {data}=await api.post('jobs/',{project:store.projectId,kind:kind.value==='api'?'api':'ui',name:(rows.length>1?'批量执行 · ':'调试 · ')+rows[0].name,mode:mode.value,payload});runDialog.value=false;router.push('/tasks/'+data.id)}finally{running.value=false}}
async function duplicate(row:any){await api.post(`entities/${row.id}/duplicate/`);load()}
function ai(row:any,operation:string){router.push({path:'/ai',query:{operation,entity:String(row.id),target:kind.value==='api'?'api':kind.value==='ui_case'?'ui_case':'case'}})}
async function retrieval(){if(!query.value)return;searching.value=true;try{hits.value=(await api.post(`entities/${detail.value.id}/search/`,{query:query.value})).data}finally{searching.value=false}}
async function importItems(){let value;try{value=JSON.parse(importText.value)}catch{ElMessage.warning('请输入有效 JSON');return}if(syncOpenapi.value)await api.post('entities/sync_openapi/',{project:store.projectId,spec:value});else await api.post('entities/import/',{project:store.projectId,items:value});importDialog.value=false;ElMessage.success('导入完成');load()}
async function install(row:any){await api.post(`entities/${row.id}/install/`);ElMessage.success('技能已安装，可在 Skill 管理中查看并关联 Agent')}
async function move(row:any,offset:number){await api.patch(`entities/${row.id}/`,{position:row.position+offset});load()}
</script>
<template><div><div class="page-heading"><div><div class="heading-eyebrow">{{section.eyebrow}}</div><h1>{{$t(section.title)}}</h1><p>{{section.description}}</p></div><div class="inline-actions"><el-button v-if="route.meta.catalog==='requirements'&&store.canEdit" @click="requirementInput?.click()"><Icon name="Upload"/>导入需求</el-button><el-button v-else @click="syncOpenapi=false;importText='';importDialog=true">{{ $t('导入 JSON') }}</el-button><el-button v-if="route.meta.catalog==='ui-testing'&&store.canEdit" type="primary" @click="router.push('/ui-testing/record?platform='+uiPlatform)"><Icon name="VideoCamera"/>录制</el-button><el-dropdown @command="exportItems"><el-button>导出<Icon name="ArrowDown"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="json">JSON</el-dropdown-item><el-dropdown-item command="xlsx">Excel（.xlsx）</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="store.canEdit" type="primary" @click="edit()"><Icon name="Plus"/>新建{{kind==='ui_case'?(uiPlatform==='app'?'App 用例':'Web 用例'):kinds[kind]?.name}}</el-button></div></div>
<div v-if="['api-testing','ui-testing'].includes(String(route.meta.catalog))" class="info-banner"><Icon name="InfoFilled"/><div><strong>{{route.meta.catalog==='ui-testing'?'Playwright Chromium · 本地 Worker 执行':'真实 HTTP 请求 · 声明式断言'}}</strong><p>{{ $t('真实执行需管理员将目标加入 TESTPILOT_ALLOWED_TARGETS。脚本使用声明式操作，不执行任意 Python、JavaScript 或 Shell。') }}</p></div></div>
<div v-if="route.meta.catalog==='skill-library'" class="info-banner"><Icon name="Lock"/><div><strong>{{ $t('受控技能安装') }}</strong><p>{{ $t('安装清单中的专项指令，可关联 Agent。安装器不运行远程安装脚本或系统命令。') }}</p></div></div>
<section class="panel catalog-panel"><el-tabs v-model="kind" @tab-change="filter"><el-tab-pane v-for="k in section.tabs" :key="k" :label="$t(kinds[k].name)" :name="k"/></el-tabs><div v-if="kind==='ui_case'" class="case-actions"><el-radio-group v-model="uiPlatform"><el-radio-button value="app">App 用例</el-radio-button><el-radio-button value="web">Web 用例</el-radio-button></el-radio-group><span class="helper">{{uiPlatform==='app'?'Android / Mobile MCP，用例按设备执行':'浏览器 / Playwright，用例按网页环境执行'}}</span></div><div class="list-toolbar"><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索名称')" clearable @keyup.enter="filter" @clear="filter" style="width:220px"/><el-button @click="filter">{{ $t('查询') }}</el-button></div><div v-if="['api','ui_case','ui_flow'].includes(kind)" class="inline-actions"><el-select v-model="environment" clearable :value-on-clear="null" :placeholder="$t('选择环境')" style="width:150px"><el-option v-for="e in envs" :key="e.id" :label="e.name" :value="e.id"/></el-select><el-select v-model="mode" style="width:115px"><el-option :label="$t('真实执行')" value="live"/><el-option :label="$t('模拟模式')" value="simulation"/></el-select><el-button v-if="kind==='ui_case'&&store.canEdit" :disabled="!selected.length" @click="openProfileApply">应用公共配置</el-button><el-button v-if="kind==='ui_case'&&store.canEdit" type="primary" :disabled="!selected.some((row:any)=>row.config?.automation_status==='needs_mapping'||row.config?.verification_status==='unverified')" :loading="converting" @click="convertSelected">转为可执行步骤</el-button><el-button v-if="kind!=='ui_flow'&&store.canEdit" type="primary" :disabled="!selected.length||selected.some((row:any)=>row.config?.automation_status==='needs_mapping')" @click="prepareRun(selected)">{{ $t('批量运行') }}</el-button><el-button v-if="kind==='api'&&store.canEdit" @click="syncOpenapi=true;importText='';importDialog=true">{{ $t('同步 OpenAPI') }}</el-button></div></div>
<el-table :data="items" v-loading="loading" @selection-change="(v:any[])=>selected=v"><el-table-column type="selection" width="44" :selectable="()=>true"/><el-table-column :label="$t('名称')" min-width="230"><template #default="{row}"><div class="table-title"><span class="table-icon"><Icon :name="kinds[kind].icon"/></span><div><el-button link class="asset-name" @click="view(row)">{{row.name}}</el-button><small>{{kinds[kind].name}} · #{{row.id}} <span v-if="kind==='ui_flow'">· {{row.config?.platform==='app'?'App':'Web'}} · {{row.config?.case_ids?.length||0}} 条用例 · {{row.config?.status==='ready'?'就绪':'草稿'}}</span><span v-if="kind==='ui_case'&&row.config?.automation_status==='needs_mapping'">· 待配置执行</span><span v-if="kind==='ui_case'&&row.config?.executor==='mobile-mcp'"> · Android / Mobile MCP</span><span v-if="kind==='ui_case'&&row.config?.verification_status==='unverified'"> · 未验证</span></small><small v-if="kind==='ui_case'&&row.config?.platform==='app'" style="display:block;color:var(--el-text-color-secondary)">测试 App：{{row.config?.app_name||'未配置'}} · 包名：{{row.config?.package_name||'未配置'}} · 设备：{{row.config?.device_id||'未配置'}}</small><small v-if="kind==='ui_case'&&row.config?.platform==='web'" style="display:block;color:var(--el-text-color-secondary);max-width:520px;overflow:hidden;text-overflow:ellipsis">Web URL：{{row.config?.base_url||'未配置'}}</small></div></div></template></el-table-column><el-table-column v-if="kind==='machine'" label="连接机型" min-width="190"><template #default="{row}">{{machineStatuses[row.id]?.model||'—'}}<small v-if="machineStatuses[row.id]?.device_id" style="display:block">{{machineStatuses[row.id].device_id}}</small></template></el-table-column><el-table-column v-if="kind==='machine'" label="连接状态" min-width="170"><template #default="{row}"><el-tag :type="!machineStatuses[row.id]?.checked?'info':machineStatuses[row.id].connected?'success':'danger'">{{!machineStatuses[row.id]?.checked?'未检测':machineStatuses[row.id].connected?'连接成功':'连接失败'}}</el-tag><small style="display:block">{{machineStatuses[row.id]?.message||'尚未检测'}}</small><small v-if="machineStatuses[row.id]?.checked_at" style="display:block">{{fmt(machineStatuses[row.id].checked_at)}}</small></template></el-table-column><el-table-column v-if="kind==='ui_case'" label="类型" width="95"><template #default="{row}"><el-tag :type="row.config?.platform==='app'?'success':'info'">{{row.config?.platform==='app'?'App':'Web'}}</el-tag></template></el-table-column><el-table-column :label="$t('版本')" width="80"><template #default="{row}"><span class="mini-badge">v{{row.version}}</span></template></el-table-column><el-table-column :label="$t('更新时间')" width="140"><template #default="{row}">{{fmt(row.updated_at)}}</template></el-table-column><el-table-column :label="$t('操作')" min-width="265"><template #default="{row}"><template v-if="store.canEdit"><el-button link type="primary" @click="edit(row)">{{ $t('编辑') }}</el-button><el-button v-if="kind==='machine'" link type="primary" :loading="checkingMachines.includes(row.id)" @click="testMachine(row)">测试连接</el-button><el-button v-if="['requirement','knowledge_document'].includes(kind)" link @click="upload(row)">{{ $t('上传解析') }}</el-button><el-button v-if="kind==='requirement'" link type="primary" @click="ai(row,'review')">{{ $t('评审') }}</el-button><el-button v-if="kind==='requirement'" link @click="ai(row,'split')">{{ $t('拆分') }}</el-button><el-button v-if="kind==='requirement'" link type="primary" @click="ai(row,'design')">功能拆解与模块用例</el-button><el-button v-if="['api','ui_case'].includes(kind)" link type="primary" :disabled="kind==='ui_case'&&row.config?.automation_status==='needs_mapping'" @click="prepareRun([row])">{{ $t('运行') }}</el-button><el-button v-if="kind==='ui_flow'" link type="primary" @click="prepareRun([row])">执行流程</el-button><el-button v-if="['api','ui_case','requirement'].includes(kind)" link @click="ai(row,'generate')">{{ $t('AI 编写') }}</el-button><el-button v-if="kind==='skill_source'" link type="primary" @click="install(row)">{{ $t('安装') }}</el-button><el-dropdown><el-button link>{{ $t('更多') }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="['api','ui_case'].includes(kind)" @click="ai(row,'optimize')">{{ $t('AI 编辑 / 修复') }}</el-dropdown-item><el-dropdown-item @click="duplicate(row)">{{ $t('复制') }}</el-dropdown-item><el-dropdown-item @click="move(row,-1)">{{ $t('上移排序') }}</el-dropdown-item><el-dropdown-item @click="remove(row)">{{ $t('删除') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><el-button v-else link @click="view(row)">{{ $t('查看') }}</el-button></template></el-table-column><template #empty><el-empty :description="`暂无${kinds[kind]?.name}，创建第一条记录开始使用`"/></template></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :total="total" layout="prev, pager, next" @current-change="load"/></div></section>
<input ref="fileInput" type="file" accept=".txt,.md,.pdf,.doc,.docx,.json,.csv" style="display:none" @change="onFile"/>
<input ref="requirementInput" type="file" accept=".md,.doc,.docx" style="display:none" @change="importRequirement"/>
<el-dialog v-model="dialog" :title="`${form.id?'编辑':'创建'}${kinds[kind]?.name}`" width="780px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item :label="$t('名称')"><el-input v-model="form.name" maxlength="150"/></el-form-item><template v-if="kind==='ui_flow'"><div class="case-actions"><strong>流程平台</strong><el-radio-group :model-value="form.config.platform" @change="(value:string)=>{form.config.platform=value;loadFlowCases(true)}"><el-radio-button value="web">Web</el-radio-button><el-radio-button value="app">App</el-radio-button></el-radio-group></div><el-form-item label="流程状态"><el-select v-model="form.config.status"><el-option label="草稿" value="draft"/><el-option label="就绪" value="ready"/></el-select></el-form-item><el-form-item label="UI 环境（可选）"><el-select v-model="form.config.environment_id" clearable :value-on-clear="null" placeholder="运行时可覆盖"><el-option v-for="env in envs" :key="env.id" :label="env.name" :value="env.id"/></el-select></el-form-item><el-form-item label="关联 UI 用例"><el-select v-model="form.config.case_ids" multiple filterable collapse-tags collapse-tags-tooltip placeholder="选择同平台可执行用例"><el-option v-for="item in flowCases" :key="item.id" :value="item.id" :disabled="form.config.status==='ready'&&item.config?.automation_status==='needs_mapping'" :label="`${item.name}${item.config?.automation_status==='needs_mapping'?'（待配置）':''}`"/></el-select></el-form-item><div class="flow-list"><div v-for="(id,index) in form.config.case_ids" :key="id"><span class="step-number">{{Number(index)+1}}</span><span>{{flowCases.find(item=>item.id===id)?.name||('用例 #'+id)}}</span><el-button link :disabled="Number(index)===0" @click="moveFlowCase(Number(index),-1)">上移</el-button><el-button link :disabled="Number(index)===form.config.case_ids.length-1" @click="moveFlowCase(Number(index),1)">下移</el-button></div></div><p class="helper">按列表顺序串行执行并汇总到同一任务报告。流程就绪后需确保所有关联用例也已配置完成。</p></template><UiCaseSteps v-if="kind==='ui_case'" :config="form.config" :page-objects="pageObjects" :resources="uiResources" @mode="setUiStepMode"/><el-form-item v-if="['module','requirement','knowledge_document','ui_case'].includes(kind)" :label="kind==='knowledge_document'?'所属知识库':kind==='ui_case'?'所属功能模块':'父级节点'"><el-select v-model="form.parent" clearable :value-on-clear="null"><el-option v-for="p in parents.filter(x=>x.id!==form.id)" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item v-if="kinds[kind]?.content" :label="$t('正文 / 指令')"><el-input v-model="form.content" type="textarea" :rows="8" :placeholder="$t('输入完整业务描述、验收标准或团队测试规范')"/></el-form-item><el-form-item v-if="kind==='machine'" label="本地测试机类型"><el-select :model-value="form.config?.executor" @change="changeMachineExecutor"><el-option label="本地 Chromium 浏览器" value="local-playwright-chromium"/><el-option label="本地 Android 设备（ADB）" value="local-android-adb"/></el-select></el-form-item><template v-if="kind==='ui_data'"><el-form-item label="公共数据类型"><el-select v-model="form.config.data_type"><el-option label="测试变量" value="variables"/><el-option label="App 执行配置" value="app_profile"/><el-option label="Web 执行配置" value="web_profile"/></el-select></el-form-item><template v-if="form.config.data_type==='app_profile'"><el-form-item label="测试 App 名称"><el-input v-model="form.config.app_profile.app_name" placeholder="金姆脉知"/></el-form-item><el-form-item label="Android 包名"><el-input v-model="form.config.app_profile.package_name" placeholder="com.jinmu.pulseoasis"/></el-form-item><el-form-item label="设备 ID"><el-input v-model="form.config.app_profile.device_id" placeholder="已连接设备 serial"/></el-form-item><el-form-item label="Mobile MCP 资源"><el-select v-model="form.config.app_profile.mcp_resource_id" placeholder="选择已启用的真实执行资源"><el-option v-for="resource in uiResources.filter((item:any)=>item.enabled&&item.mode==='live')" :key="resource.id" :label="resource.name" :value="resource.id"/></el-select></el-form-item></template><template v-else-if="form.config.data_type==='web_profile'"><el-form-item label="Web 程序 URL"><el-input v-model="form.config.web_profile.base_url" placeholder="https://example.test/login"/></el-form-item><el-form-item label="浏览器"><el-select v-model="form.config.web_profile.browser"><el-option label="Chromium" value="chromium"/></el-select></el-form-item><p class="helper">目标域名仍需加入 TESTPILOT_ALLOWED_TARGETS；配置应用到用例后，执行时可选择 UI 环境覆盖此 URL。</p></template><el-form-item label="公共测试变量（JSON）"><el-input v-model="configText" class="code-input" type="textarea" :rows="7" placeholder="例如：{&quot;valid_phone_number&quot;:&quot;测试号码&quot;}"/></el-form-item></template><el-form-item v-else-if="kind!=='ui_case'" :label="$t('结构化配置（JSON）')"><el-input v-model="configText" class="code-input" type="textarea" :rows="kind==='api'?16:7"/></el-form-item><p v-if="kind==='knowledge'" class="helper">embedding_model / reranker_model 填模型 ID，null 使用本地哈希向量检索。可用模型：{{models.map(m=>`${m.name} #${m.id}`).join('，')||'暂无'}}</p><p v-if="kind==='api'" class="helper">{{ $t('支持 status、json_equals、contains、duration_lt、db_equals 断言。extract 使用点路径。before/after 支持 set、uuid、timestamp、concat。变量使用双花括号引用。') }}</p><p v-if="kind==='machine'" class="helper">Android 设备可在配置中填写 serial 指定序列号；留空时自动识别唯一设备。连接成功仅表示本机可识别该设备，当前 UI 用例运行器仍使用 Chromium。</p><p v-if="kind==='database'" class="helper">{{ $t('当前支持 backend/test_databases 中的 SQLite 只读校验，SQL 仅允许 SELECT。') }}</p></el-form><template #footer><el-button @click="dialog=false">{{ $t('取消') }}</el-button><el-button type="primary" :loading="saving" @click="save">{{ $t('保存版本') }}</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" :title="detail?.name" size="700px" @close="detail=null"><template v-if="detail"><div class="inline-actions"><span class="mini-badge">v{{detail.version}}</span><span class="muted">{{fmt(detail.updated_at)}}</span><el-button v-if="store.canEdit" link type="primary" @click="edit(detail)">{{ $t('在线编辑') }}</el-button></div><template v-if="detail.kind==='knowledge'"><div class="knowledge-stats"><div><b>{{stats?.documents||0}}</b><span>{{ $t('文档') }}</span></div><div><b>{{stats?.chunks||0}}</b><span>{{ $t('分块') }}</span></div><div><b>{{stats?.characters||0}}</b><span>{{ $t('字符') }}</span></div></div><div class="inline-actions"><el-input v-model="query" :placeholder="$t('检索业务规则、需求与接口文档')" @keyup.enter="retrieval"/><el-button type="primary" :loading="searching" @click="retrieval">{{ $t('检索') }}</el-button></div><article v-for="h in hits" :key="h.document_id+':'+h.chunk" class="retrieval-hit"><strong>{{h.document}} · 块 {{h.chunk+1}}</strong><span class="mini-badge">{{h.score}}</span><p>{{h.text}}</p><small>{{h.embedding}}</small></article></template><div v-else class="document-content" style="margin-top:20px">{{detail.content||JSON.stringify(detail.config,null,2)}}</div><h3 style="margin:24px 0 12px">{{ $t('文件附件') }}</h3><div v-for="f in files" :key="f.id" class="file-row"><a :href="f.url">{{f.name}}</a><small>{{fmt(f.created_at)}}</small></div><p v-if="!files.length" class="helper">{{ $t('暂无附件') }}</p><h3 style="margin:24px 0 12px">{{ $t('版本记录') }}</h3><el-collapse><el-collapse-item v-for="v in versions" :key="v.version" :title="`v${v.version} · ${fmt(v.created_at)}`"><pre class="json-result">{{v.content||JSON.stringify(v.config,null,2)}}</pre><el-button v-if="store.canEdit&&v.version!==detail.version" @click="restore(v)">{{ $t('恢复此版本为新版本') }}</el-button></el-collapse-item></el-collapse></template></el-drawer>
<el-dialog v-model="profileDialog" :title="'应用 '+(uiPlatform==='app'?'App':'Web')+' 公共配置'" width="520px"><el-form label-position="top"><el-form-item label="选择公共配置"><el-select v-model="profileId" style="width:100%"><el-option v-for="profile in publicProfiles" :key="profile.id" :label="profile.name" :value="profile.id"/></el-select></el-form-item></el-form><p class="helper">仅应用到当前列表中已勾选的用例。用例步骤保持独立；公共配置和变量在运行时合并。</p><template #footer><el-button @click="profileDialog=false">取消</el-button><el-button type="primary" :loading="applyingProfile" @click="applyProfile">应用到 {{selected.length}} 条用例</el-button></template></el-dialog><el-dialog v-model="runDialog" title="执行前数据准备" width="680px" :close-on-click-modal="false"><PreparedDataSelect :disabled="running" @apply="value=>{preparationText=JSON.stringify(value,null,2)}"/><el-form-item v-if="kind==='api'" label="失败后的 AI 分析模型（可选）"><el-select v-model="failureAnalysisModelId" clearable placeholder="未选择：仅使用本地规则分诊"><el-option v-for="model in failureAnalysisModels" :key="model.id" :value="model.id" :label="`${model.name} · ${modelLocation(model)}`"/></el-select><p class="helper">仅分析失败用例，不参与接口请求。<el-button v-if="!failureAnalysisModels.length" link type="primary" @click="router.push('/resources/model')">前往模型管理</el-button></p></el-form-item><div class="inline-actions"><span class="helper">数据准备示例（需按当前测试环境替换）：</span><el-button link type="primary" :disabled="running" @click="fillPreparationExample">填入示例</el-button></div><el-form v-if="kind==='ui_case'&&uiPlatform==='web'" label-position="top"><div class="form-grid"><el-form-item label="重复回放次数"><el-input-number v-model="repeatCount" :min="1" :max="20"/></el-form-item><el-form-item label="卡顿阈值（毫秒）"><el-input-number v-model="stallThresholdMs" :min="500" :max="60000" :step="500"/></el-form-item></div><p class="helper">每轮独立启动浏览器上下文，记录逐轮通过率、页面异常、超阈值步骤、截图、视频和 Trace。真实执行模式才会启动浏览器。</p></el-form><el-form v-if="kind==='api'" label-position="top"><el-form-item label="请求地址"><el-input v-model="requestBaseUrl" placeholder="例如：https://api.example.com"/></el-form-item><el-form-item label="请求路径"><el-input v-model="requestPath" :placeholder="pendingRows.length>1?'批量执行留空，使用各用例自身路径':'例如：/v1/login'"/></el-form-item><el-form-item label="请求参数（JSON）"><el-input v-model="requestParamsText" type="textarea" :rows="6" class="code-input" placeholder='{"username":"tester"}'/></el-form-item></el-form><el-alert v-if="kind==='ui_case'&&referencedRunVariables.length" type="warning" :closable="false" show-icon title="用例依赖运行时变量"><template #default><span>当前用例引用：{{referencedRunVariables.join('、')}}。请在下面填写测试数据，或确认所选 UI 环境已配置这些变量；不要将真实密码保存在用例步骤中。</span></template></el-alert><p class="helper">临时变量会覆盖环境中的同名变量，可在请求地址、路径、参数或 UI 步骤中使用双花括号引用。</p><el-input v-model="preparationText" type="textarea" :rows="5" class="code-input" placeholder='{"token":"临时令牌","order_id":"10001"}'/><p class="helper">批量执行时填写的请求路径和参数会应用到全部选中接口；任务日志只记录变量名，不记录临时变量值。</p><template #footer><el-button @click="runDialog=false">取消</el-button><el-button type="primary" :loading="running" @click="submitRun">准备数据并执行</el-button></template></el-dialog>
<el-dialog v-model="importDialog" :title="syncOpenapi?'同步 OpenAPI 定义':'导入资产 JSON'" width="700px"><p class="helper">{{syncOpenapi?'粘贴包含 paths 的 OpenAPI JSON。相同方法与路径会更新为新版本。':'粘贴导出的 JSON 数组，记录将复制到当前项目。一次最多 200 条。'}}</p><el-input v-model="importText" type="textarea" :rows="15" class="code-input"/><template #footer><el-button @click="importDialog=false">{{ $t('取消') }}</el-button><el-button type="primary" @click="importItems">{{ $t('导入') }}</el-button></template></el-dialog>
</div></template>
